import { Component, ElementRef, EventEmitter, forwardRef, Input, OnInit, Output, ViewChild, ViewEncapsulation } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { ControlNameModule, espdAbstractInputComponentInjectionToken, EspdAbstractInputDirective, EspdFormControl } from 'espd-common/forms/api';
import { defaultDatePickerConfig } from 'espd-common/forms/date-picker/config';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { MessageConfig, MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { BsDatepickerConfig, BsDatepickerModule } from 'ngx-bootstrap/datepicker';

@Component({
	selector: 'espd-search',
	templateUrl: './search.component.html',
	imports: [
		ReactiveFormsModule,
		BsDatepickerModule,
		ControlNameModule,
		IconDirective,
		InputScaffoldComponent,
		MessageModule
	],
	styleUrls: ['./search.component.scss'],
	encapsulation: ViewEncapsulation.None,
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => SearchComponent) }]
})
export class SearchComponent extends EspdAbstractInputDirective implements OnInit {

	@Input()
	public searchButtonIcon: string = 'rvt-magnifying-glass';

	@Input()
	public searchButtonText: MessageConfig | string = { key: 'common.search' };

	@Input()
	public datePickerConfig?: Partial<BsDatepickerConfig>;

	@Output()
	/* eslint-disable @angular-eslint/no-output-native */
	public search: EventEmitter<string | Date> = new EventEmitter();

	@ViewChild('input', { read: ElementRef })
	public inputElement?: ElementRef;

	@ViewChild(InputScaffoldComponent, { read: ElementRef })
	protected scaffoldElement?: ElementRef;

	public get datePickerConfiguration(): Partial<BsDatepickerConfig> | undefined {
		if (this.datePickerConfig) {
			return { ...defaultDatePickerConfig, ...this.datePickerConfig };
		} else {
			return undefined;
		}
	}

	public ngOnInit(): void {
		super.ngOnInit();
		if (!this.control) {
			this.control = new EspdFormControl<string | Date>(null);
		}
	}

	public doSearch(event?: Event): void {
		event?.preventDefault();
		event?.stopPropagation();

		if (!this.disabled) {
			this.search.emit(this.control.value);
		}
	}

	public clearSearchButtonAction(event: Event): void {
		event.preventDefault();
		event.stopPropagation();
		this.clearSearchTerms();
		this.focus();
	}

	public clearSearchTerms(): void {
		this.control.reset('');
	}

	/** @deprecated use focus() */
	public focusSearchInput(): void {
		this.focus();
	}

	public focus(target: 'control' | 'container' = 'control'): void {
		(target === 'control'
			? this.inputElement
			: this.scaffoldElement
		)?.nativeElement.focus();
	}
}